"""Readable replacements for the 122 interrupted foundations drafts.

Never edits registered arrays. Emits hash-guarded proposals for the parent's
versioned publisher. Published IDs, titles and original source objects survive.
"""
from copy import deepcopy
import hashlib
import json
from pathlib import Path

ROOT=Path(__file__).resolve().parents[3]
BANK=ROOT/'tools/problem-bank'
EDITS={}

def contracts(text):
    for row in text.strip().splitlines():
        if row.strip():
            ident,task,fixture,expected,boundary=row.split('|')
            assert ident not in EDITS
            EDITS[ident]=(task,fixture,expected,boundary)

