def digest(value):
    return hashlib.sha256(json.dumps(value,sort_keys=True,separators=(',',':'),ensure_ascii=False).encode()).hexdigest()

def main():
    proposals=[]
    originals={}
    for tool in ('python','sql'):
        name=f'{tool}-batch3.json'
        source=json.loads((BANK/name).read_text(encoding='utf-8'))
        for original in source:
            if original.get('publication_status')!='draft':continue
            ident=original['id']
            assert ident in EDITS,ident
            task,fixture,expected,boundary=EDITS[ident]
            replacement=deepcopy(original)
            replacement.update(scenario=task,task=task,
                inputs={'fixture_contract':fixture,'environment':'Synthetic fixtures with injected transport or isolated learner-owned training targets only.'},
                expected_output={'contract':expected},
                constraints=[boundary,'Preserve source inputs,actual attempts and unrelated files; use only synthetic credentials.'],
                acceptance_criteria=['Observe the specified result: '+expected,
                    'Verify the stated boundary: '+boundary,
                    'Submit code/configuration,actual results and all assistance used; expected output alone is not execution evidence.'],
                progressive_hints=['Trace the smallest supplied input by hand and name the expected output grain.',
                    'Check this specific boundary on a separate test fixture: '+boundary,
                    'Reduce the first failing case,compare expected and observed evidence,and reconstruct the bounded task one checked step at a time.'],
                publication_status='published',draft_reason=None,
                authoring_batch='foundations-third-batch-readable-promotions')
            assert replacement['id']==original['id'] and replacement['title']==original['title']
            proposals.append({'source_file':name,'original_draft_id':ident,
                'original_draft_sha256':digest(original),'problem':replacement})
            originals[ident]=digest(original)
    assert len(proposals)==len(EDITS)==122,(len(proposals),len(EDITS))
    wrapper={'publication_status':'unregistered_proposals','author':'foundations-readable-recovery',
        'proposals':proposals,'quality_review':'Each interrupted contract was explicitly rewritten with readable task,fixture,expected behavior and boundary; no published source object was changed.'}
    target=BANK/'foundations-draft-promotions.json'
    target.write_text(json.dumps(wrapper,indent=2,ensure_ascii=False)+'\n',encoding='utf-8')
    checkpoint={'status':'proposals_frozen_for_parent_publication','proposals':len(proposals),
        'by_tool':{tool:sum(p['problem']['tool_id']==tool for p in proposals) for tool in ('python','sql')},
        'original_draft_hashes':originals,'proposal_sha256':hashlib.sha256(target.read_bytes()).hexdigest(),
        'source_files_modified':False}
    (BANK/'authors/foundations-promotions-checkpoint.json').write_text(json.dumps(checkpoint,indent=2)+'\n',encoding='utf-8')
    print(json.dumps({k:v for k,v in checkpoint.items() if k!='original_draft_hashes'},indent=2))

if __name__=='__main__':main()
